<?php $escape = static fn (mixed $value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8'); $activeDevices = array_values(array_filter($devices, static fn (array $device): bool => (int) ($device['active'] ?? 0) === 1)); ?><section class="section"><header class="admin-header"><div><h1>Notificaciones</h1><p>Consulta tus avisos y activa la entrega directa en tu celular.</p></div><a href="<?php echo $baseUrl; ?>/admin/tickets" class="btn btn--secondary">Ver tickets</a></header><div class="card panel-card"><div class="notification-summary"><strong><?php echo (int) $unreadCount; ?></strong><span>notificación<?php echo $unreadCount === 1 ? '' : 'es'; ?> sin leer</span></div></div><div class="card panel-card push-settings"><h2>Notificaciones en el celular</h2><?php if (!$pushConfigured): ?><p class="ticket-meta">La entrega móvil aún no está configurada en este entorno.</p><?php else: ?><p>Actívalas en cada teléfono o navegador donde quieras recibir avisos. Puedes tener varios dispositivos con la misma cuenta.</p><details class="ticket-meta"><summary>Cómo activarlas</summary><p>Android: usa Chrome con HTTPS y acepta el permiso cuando aparezca. iPhone: abre el panel en Safari, agrégalo a la pantalla de inicio y actívalo desde esa aplicación.</p></details><button type="button" class="btn" data-push-enable>Activar en este dispositivo</button><p class="ticket-meta" data-push-status><?php echo $activeDevices ? 'Hay ' . count($activeDevices) . ' dispositivo' . (count($activeDevices) === 1 ? '' : 's') . ' activo' . (count($activeDevices) === 1 ? '' : 's') . '.' : 'En Android funciona desde el navegador. En iPhone agrega primero el panel a la pantalla de inicio.'; ?></p><?php endif; ?><?php if ($devices): ?><h3>Dispositivos registrados</h3><ul class="push-device-list"><?php foreach ($devices as $device): ?><li><span><?php echo $escape($device['platform']); ?> · <?php echo $escape((int) ($device['active'] ?? 0) === 1 ? 'Activo' : 'Desactivado'); ?> · <?php echo $escape($device['last_used_at'] ?: 'Sin actividad'); ?></span><?php if ((int) ($device['active'] ?? 0) === 1): ?><form method="post"><input type="hidden" name="_csrf_token" value="<?php echo $escape($_SESSION['_csrf_token'] ?? ''); ?>"><input type="hidden" name="action" value="deactivate"><input type="hidden" name="device_id" value="<?php echo (int) $device['id']; ?>"><button class="btn btn--secondary" type="submit">Desactivar</button></form><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?><form method="post" class="admin-form push-preferences"><input type="hidden" name="_csrf_token" value="<?php echo $escape($_SESSION['_csrf_token'] ?? ''); ?>"><input type="hidden" name="action" value="preferences"><h3>Preferencias</h3><label class="admin-form__check"><input type="checkbox" name="assignments" <?php echo !empty($preferences['assignments']) ? 'checked' : ''; ?>> Asignaciones y reasignaciones</label><label class="admin-form__check"><input type="checkbox" name="observations" <?php echo !empty($preferences['observations']) ? 'checked' : ''; ?>> Nuevas observaciones</label><label class="admin-form__check"><input type="checkbox" name="status_changes" <?php echo !empty($preferences['status_changes']) ? 'checked' : ''; ?>> Cambios de estado</label><button class="btn btn--secondary" type="submit">Guardar preferencias</button></form></div><?php if (!$notifications): ?><div class="card panel-card"><div class="ticket-observation-empty">No tienes notificaciones de asignación por ahora.</div></div><?php else: ?><div class="card panel-card"><div class="notification-list"><?php foreach ($notifications as $notification): ?><?php $actor = trim((string) ($notification['actor_display_name'] ?? $notification['actor_username'] ?? '')); ?><article class="notification-item <?php echo empty($notification['is_read']) ? 'notification-item--unread' : 'notification-item--read'; ?>"><div class="notification-item__body"><div class="notification-item__header"><h3><?php echo $escape($notification['title']); ?></h3><?php if (empty($notification['is_read'])): ?><span class="sidebar__badge">Nueva</span><?php endif; ?></div><p><?php echo $escape($notification['message']); ?></p><div class="ticket-meta"><?php echo $escape(date('d/m/Y H:i', strtotime($notification['created_at']))); ?><?php if ($actor): ?> · Actor: <?php echo $escape($actor); ?><?php endif; ?></div></div><div class="notification-item__actions"><a href="<?php echo $baseUrl; ?>/admin/tickets/<?php echo (int) $notification['ticket_id']; ?>?return=<?php echo urlencode('/admin/notificaciones'); ?>" class="btn btn--secondary">Abrir ticket</a></div></article><?php endforeach; ?></div></div><?php endif; ?></section>
